    private final class Preview extends View {private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);Preview(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas canvas){super.onDraw(canvas);int color=LIME;try{color=Color.parseColor("#"+MainActivity.this.color());}catch(IllegalArgumentException ignored){}boolean animate=foreground&&android.animation.ValueAnimator.areAnimatorsEnabled()&&state.optBoolean("running");double time=animate?SystemClock.uptimeMillis()/1000.0:0;float w=getWidth()/28f;for(int i=0;i<28;i++){float level=scene.optString("mode").equals("static")?1f:(float)(.18+.82*Math.pow(.5+.5*Math.sin(i*2.17+time*scene.optDouble("speed",65)/25),3));paint.setColor(color);paint.setAlpha((int)(255*level*scene.optDouble("brightness",100)/100));paint.setShadowLayer(dp(10),0,0,color);float h=dp(20)+dp(38)*level;canvas.drawRoundRect(i*w+dp(2),(getHeight()-h)/2,(i+1)*w-dp(2),(getHeight()+h)/2,dp(5),dp(5),paint);}if(animate)postInvalidateDelayed(33);}}
